using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 void TalentChecks(){var original=game;string selected=selectedTalent;try{
  game=new ExpeditionGame(ProjectSettings.GlobalizePath("user://tests/talents-"+Guid.NewGuid()+".json")){NoDiskSave=true};var career=game.Career;career.Gain(career.Need-career.Xp+30);MigrationChecks.Assert(career.Level==2&&career.Xp==30&&career.Points==1,"Main XP overflow and talent point award");MigrationChecks.Assert(!career.Learn("headshot")&&career.Points==1,"Talent level/prerequisite gate");career.Level=4;career.Xp=100;selectedTalent="health";ShowTalentTree();
