  double hp=game.Life.Health;Press();Press();MigrationChecks.Assert(career.Rank("health")==2&&career.Points==1&&game.MaxHealth==120&&game.Life.Health==hp,"Talent UI spends points, changes stats and does not heal");MigrationChecks.Assert(!career.Learn("health")&&career.Points==1,"Maximum talent rank / no duplicate spending");career.Xp=career.Need*.8;game.Skills.Die();MigrationChecks.Assert(career.Level==4&&career.Xp==0&&career.Rank("health")==2&&career.Points==1,"Death retains main level, talents and points");var copy=Json.Read<ExpeditionSurvivor>(Json.Write(game.Skills));copy.Normalize();MigrationChecks.Assert(copy.Career.Level==4&&copy.Career.Rank("health")==2,"Portable talent serialization");
  game.ResetTalents();MigrationChecks.Assert(career.Points==3&&career.Spent==0,"Free respec refunds exactly earned points");career.Level=20;foreach(string id in new[]{"health","armor","recovery","guard","guard"})MigrationChecks.Assert(career.Learn(id),"Toughness branch / "+id);MigrationChecks.Assert(!career.Learn("resolve"),"Capstone requires six branch points");career.Learn("health");MigrationChecks.Assert(career.Learn("resolve"),"Capstone unlocked at level twenty / branch investment");game.Shield=0;game.Life.Health=20;game.Hurt(1);MigrationChecks.Assert(game.Life.Health>10&&game.Life.Wounds.Count==1&&game.Life.Wounds[0].Blood==600,"Impact reduction never prevents wound bleeding");game.Life.Patch();game.Life.TickWounds(1199);MigrationChecks.Assert(game.Life.Wounds.Count==1,"Talents preserve full wound healing duration");game.Life.TickWounds(1);MigrationChecks.Assert(game.Life.Wounds.Count==0,"Bandage heals at twenty minutes");
  career.Level=29;career.Xp=0;career.Gain(career.Need+50000);MigrationChecks.Assert(career.Level==30&&career.Xp==0,"Main level cap");career.Gain(double.PositiveInfinity);MigrationChecks.Assert(career.Xp==0,"Nonfinite main XP rejected");var old=new ExpeditionSurvivor{Career=null};old.Strength.Level=10;old.Crafting.Level=4;old.Normalize();MigrationChecks.Assert(old.Career.Level==5&&old.Career.Points==4,"Existing activity levels receive migration credit");GD.Print("PASS / main XP, point awards, talent button actions, prerequisites/rank caps, effective stats, no instant healing, death retention, save roundtrip, refunds, capstones, unchanged bleeding duration and legacy level credit");
 }finally{CloseMenu();game=original;selectedTalent=selected;}}
